import{_ as a,o as e,c as n,a0 as t}from"./chunks/framework.DqMqoJl9.js";const i="/assets/1_4.C--f1r3S.png",b=JSON.parse('{"title":"远程登录","description":"","frontmatter":{},"headers":[],"relativePath":"linux/telnet.md","filePath":"linux/telnet.md","lastUpdated":1791039142000}'),l={name:"linux/telnet.md"};function p(r,s,o,c,d,h){return e(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="远程登录" tabindex="-1">远程登录 <a class="header-anchor" href="#远程登录" aria-label="Permalink to &quot;远程登录&quot;">​</a></h1><h2 id="ssh" tabindex="-1">ssh <a class="header-anchor" href="#ssh" aria-label="Permalink to &quot;ssh&quot;">​</a></h2><h3 id="加密算法" tabindex="-1">加密算法 <a class="header-anchor" href="#加密算法" aria-label="Permalink to &quot;加密算法&quot;">​</a></h3><h4 id="对称加密算法" tabindex="-1">对称加密算法 <a class="header-anchor" href="#对称加密算法" aria-label="Permalink to &quot;对称加密算法&quot;">​</a></h4><p>采用单钥密码系统的加密方法，同一个密钥可以同时用作信息的加密和解密，这种加密方法称为对称加密，也称为单秘钥加密</p><p><img src="'+i+`" alt=""></p><h4 id="非对称加密算法" tabindex="-1">非对称加密算法 <a class="header-anchor" href="#非对称加密算法" aria-label="Permalink to &quot;非对称加密算法&quot;">​</a></h4><p>非对称加密算法又名“公开秘钥加密算法”，非对称加密算法需要两个秘钥：公开秘钥和私有秘钥</p><p>非对称加密与对称加密相比，其安全性更好：对称加密的通信双方使用相同的秘钥，如果一方的秘钥遭泄露，那么整个通信就会被破解。 而非对称加密使用一对秘钥，一个用来加密，一个用来解密，而且公钥是公开的，秘钥是自己保存的，不需要像对称加密那样在通信之前要先同步秘钥</p><h3 id="ssh使用" tabindex="-1">ssh使用 <a class="header-anchor" href="#ssh使用" aria-label="Permalink to &quot;ssh使用&quot;">​</a></h3><p>SSH (Secure Shell)安全外壳协议，主要用于远程登录</p><p>假定你要以用户名user，登录远程主机host</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">$ ssh user@host</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果你是第一次登录对方主机，系统会出现下面的提示：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ ssh user@host</span></span>
<span class="line"><span>The authenticity of host &#39;host (12.18.429.21)&#39; can&#39;t be established.</span></span>
<span class="line"><span>RSA key fingerprint is 98:2e:d7:e0:de:9f:ac:67:28:c2:42:2d:37:16:58:4d.</span></span>
<span class="line"><span>Are you sure you want to continue connecting (yes/no)?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这段话的意思是，无法确认host主机的真实性，只知道它的公钥指纹，还想继续连接吗</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>当远程主机的公钥被接受以后，它就会被保存在文件$HOME/.ssh/known_hosts之中。下次再连接这台主机，系统就会认出它的公钥已经保 存在本地了，从而跳过警告部分，直接提示输入密码</p></div><h3 id="公钥自动登录" tabindex="-1">公钥自动登录 <a class="header-anchor" href="#公钥自动登录" aria-label="Permalink to &quot;公钥自动登录&quot;">​</a></h3><p>公钥登录就是用户将自己的公钥储存在远程主机上。登录的时候，远程主机会向用户发送一段随机字符串，用户用自己的私钥加密后，再 发回来。远程主机用事先储存的公钥进行解密，如果成功，就证明用户是可信的，直接允许登录shell，不再要求密码</p><h4 id="_1、生成公钥" tabindex="-1">1、生成公钥 <a class="header-anchor" href="#_1、生成公钥" aria-label="Permalink to &quot;1、生成公钥&quot;">​</a></h4><p>运行结束以后，在$HOME/.ssh/目录下，会新生成两个文件：id_rsa.pub和id_rsa。前者是公钥，后者是私钥</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ ssh-keygen</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_2、将公钥传送到远程主机host上面" tabindex="-1">2、将公钥传送到远程主机host上面 <a class="header-anchor" href="#_2、将公钥传送到远程主机host上面" aria-label="Permalink to &quot;2、将公钥传送到远程主机host上面&quot;">​</a></h4><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ ssh-copy-id user@host</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果还是不行，就打开远程主机的/etc/ssh/sshd_config这个文件，检查下面几行前面&quot;#&quot;注释是否取掉。</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>RSAAuthentication yes</span></span>
<span class="line"><span>PubkeyAuthentication yes</span></span>
<span class="line"><span>AuthorizedKeysFile .ssh/authorized_keys</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>然后，重启远程主机的ssh服务</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>// ubuntu系统</span></span>
<span class="line"><span>service ssh restart</span></span>
<span class="line"><span>// debian系统</span></span>
<span class="line"><span>/etc/init.d/ssh restart</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="xshell" tabindex="-1">XShell <a class="header-anchor" href="#xshell" aria-label="Permalink to &quot;XShell&quot;">​</a></h2><p>windows远程登录工具</p><h2 id="winscp" tabindex="-1">WinSCP <a class="header-anchor" href="#winscp" aria-label="Permalink to &quot;WinSCP&quot;">​</a></h2><p>windows文件传输工具</p>`,32)])])}const m=a(l,[["render",p]]);export{b as __pageData,m as default};
